package com.bank.flags;

import java.util.Set;

public class FeatureFlag {
    private final String key;
    private boolean killSwitch;        // mutable at runtime — no redeploy
    private int rolloutPercentage;     // 0..100
    private final Set<String> enabledSegments;

    public FeatureFlag(String key, boolean killSwitch, int rolloutPercentage,
                       Set<String> enabledSegments) {
        this.key = key;
        this.killSwitch = killSwitch;
        this.rolloutPercentage = rolloutPercentage;
        this.enabledSegments = enabledSegments;
    }

    public String getKey() { return key; }
    public boolean isKillSwitch() { return killSwitch; }
    public void setKillSwitch(boolean k) { this.killSwitch = k; }     // flip instantly
    public int getRolloutPercentage() { return rolloutPercentage; }
    public void setRolloutPercentage(int p) { this.rolloutPercentage = p; }
    public Set<String> getEnabledSegments() { return enabledSegments; }
}
