package com.bank.flags;

import java.util.logging.Logger;

public class FeatureFlagService {
    private static final Logger log = Logger.getLogger(FeatureFlagService.class.getName());
    private final FeatureFlag flag;

    public FeatureFlagService(FeatureFlag flag) { this.flag = flag; }

    // Returns true if the feature is ON for this context.
    public boolean isEnabled(FlagContext ctx) {
        if (flag.isKillSwitch()) {
            log.warning(() -> flag.getKey() + " KILL SWITCH ON — disabled for everyone");
            return false;                                   // instant global off
        }
        if (flag.getEnabledSegments().contains(ctx.getSegment())) {
            log.info(() -> flag.getKey() + " ON for " + ctx.getUserId()
                + " via segment " + ctx.getSegment());
            return true;
        }
        // Stable per-user bucket: same user → same decision (no flicker).
        int bucket = Math.floorMod(ctx.getUserId().hashCode(), 100);
        boolean on = bucket < flag.getRolloutPercentage();
        log.info(() -> flag.getKey() + (on ? " ON" : " OFF") + " for " + ctx.getUserId()
            + " (bucket " + bucket + " vs " + flag.getRolloutPercentage() + "%)");
        return on;
    }

    public FeatureFlag getFlag() { return flag; }
}
