package com.bank.flags;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final FeatureFlagService flags;

    public TransferService(FeatureFlagService flags) { this.flags = flags; }

    public void transfer(FlagContext ctx, String from, String to, BigDecimal amount) {
        if (flags.isEnabled(ctx)) {
            log.info(() -> "INSTANT transfer Rs." + amount + " " + from + "→" + to
                + " for " + ctx.getUserId() + " (new path)");
        } else {
            log.info(() -> "STANDARD (T+0 batch) transfer Rs." + amount + " " + from + "→" + to
                + " for " + ctx.getUserId() + " (old path)");
        }
    }
}
