package com.bank.flags;

import java.math.BigDecimal;
import java.util.Set;
import java.util.logging.*;

public class FeatureFlagDemo {
    private static final Logger log = Logger.getLogger(FeatureFlagDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeatureFlag flag = new FeatureFlag("instant-transfer", false, 10, Set.of("internal-beta"));
        FeatureFlagService flagService = new FeatureFlagService(flag);
        TransferService transfers = new TransferService(flagService);

        FlagContext rajesh = new FlagContext("SAV2001", "internal-beta"); // beta → always on
        FlagContext priya  = new FlagContext("CUR3001", "retail");        // 10% bucket

        log.info("=== Dark launch: 10% rollout + internal-beta segment ===");
        transfers.transfer(rajesh, "SAV2001", "CUR3001", new BigDecimal("50000"));
        transfers.transfer(priya,  "CUR3001", "SAV2001", new BigDecimal("20000"));

        log.info("=== Widen rollout to 100% (no redeploy) ===");
        flag.setRolloutPercentage(100);
        transfers.transfer(priya, "CUR3001", "SAV2001", new BigDecimal("20000"));

        log.info("=== Incident! Flip KILL SWITCH off (instant, no redeploy) ===");
        flag.setKillSwitch(true);
        transfers.transfer(rajesh, "SAV2001", "CUR3001", new BigDecimal("50000"));
        transfers.transfer(priya,  "CUR3001", "SAV2001", new BigDecimal("20000"));
    }
}
